CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), username VARCHAR(32) UNIQUE NOT NULL, display_name VARCHAR(64) NOT NULL, password_hash TEXT NOT NULL, avatar TEXT, best_score INTEGER DEFAULT 0, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE challenges (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code VARCHAR(16) UNIQUE NOT NULL, creator_id UUID REFERENCES users(id), opponent_id UUID REFERENCES users(id), mode VARCHAR(16) NOT NULL, difficulty VARCHAR(16) NOT NULL, question_count INTEGER NOT NULL, seconds INTEGER NOT NULL, questions JSONB NOT NULL, state VARCHAR(16) NOT NULL DEFAULT 'pending', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE challenge_results (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), challenge_id UUID REFERENCES challenges(id), user_id UUID REFERENCES users(id), score INTEGER NOT NULL, answers JSONB NOT NULL, completed_at TIMESTAMPTZ DEFAULT now(), UNIQUE(challenge_id,user_id));
